import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/wind-and-storms/","title":"CH1.4 风、雷暴与大气现象 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.4 风、雷暴与大气现象","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/wind-and-storms/"},"readingTime":{"minutes":33.6,"words":10080},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/4.wind-and-storms.md","headers":[],"bulletin":false}`),a={name:`4.wind-and-storms.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="gust" tabindex="-1"><a class="header-anchor" href="#gust"><span>Gust</span></a></h2><p class="vc-meta"><strong>/ɡʌst/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>一阵狂风；一阵（笑声、情绪）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a gust of wind</td><td>一阵狂风</td></tr><tr><td>strong gusts</td><td>强阵风</td></tr><tr><td>gusts of up to 80 km/h</td><td>时速达 80 公里的阵风</td></tr><tr><td>a gust of laughter</td><td>一阵笑声</td></tr><tr><td>gusty winds</td><td>阵阵大风</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph records wind speed, with gusts of over 60 kilometres per hour in the afternoon.</p><blockquote><p>该图记录了风速，午后出现时速超过 60 公里的阵风。</p></blockquote><p><strong>Writing Task 2</strong> New buildings are tested against gusts far stronger than the area&#39;s average wind speed.</p><blockquote><p>新建筑要按远高于当地平均风速的阵风标准进行测试。</p></blockquote><p><strong>Speaking</strong> A gust came off the sea and took my hat straight into the water.</p><blockquote><p>一阵海风把我的帽子直接吹进了水里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>blast</td><td>一阵强风</td><td>更强调冲击力</td></tr><tr><td>squall</td><td>短时风暴</td><td>常伴随雨，持续几分钟</td></tr><tr><td>breeze</td><td>微风</td><td>强度完全相反</td></tr><tr><td>draught</td><td>穿堂风</td><td>指室内气流</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古诺尔斯语 <em>gustr</em>（一阵风）</li><li><strong>Family:</strong> gusty 阵风的 / gust 阵风</li><li><strong>Memory Tip:</strong> gust 是&quot;一下子&quot;的风，来得快去得快；breeze 是持续的和风，两者是风速轴的两端。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a gust、gusts；固定搭配 a gust of wind 不能省 of。</li><li>形容词是 gusty：gusty winds。</li><li>别与 guest（客人）混，读音相近但意思无关。</li></ul></div><div class="vocab-card"><h2 id="breeze" tabindex="-1"><a class="header-anchor" href="#breeze"><span>Breeze</span></a></h2><p class="vc-meta"><strong>/briːz/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>微风，和风；（口语）轻而易举的事</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a gentle breeze</td><td>微风</td></tr><tr><td>a sea breeze</td><td>海风</td></tr><tr><td>a light breeze</td><td>轻风</td></tr><tr><td>breeze through</td><td>轻松通过</td></tr><tr><td>shoot the breeze</td><td>闲聊</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a sea breeze forms during the day as the land heats faster than the water.</p><blockquote><p>该图显示了白天陆地升温快于水面时海风是如何形成的。</p></blockquote><p><strong>Writing Task 2</strong> Coastal cities benefit from a constant breeze that disperses air pollution.</p><blockquote><p>沿海城市受益于持续的海风，它能吹散空气污染。</p></blockquote><p><strong>Speaking</strong> There was a light breeze on the terrace, which made the heat bearable.</p><blockquote><p>露台上有微风，让暑热变得可以忍受。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gust</td><td>阵风</td><td>突然、短促，强度更大</td></tr><tr><td>draught</td><td>穿堂风</td><td>指室内气流，常含负面意味</td></tr><tr><td>wind</td><td>风</td><td>总称，不指强度</td></tr><tr><td>zephyr</td><td>西风；微风</td><td>文学用语，日常不用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 可能源自西班牙语 <em>brisa</em>（东北信风）</li><li><strong>Family:</strong> breezy 有微风的；轻松愉快的 / breeze 微风</li><li><strong>Memory Tip:</strong> 记住&quot;舒服的小风&quot;这个画面，就能和 gust（猛一下）、gale（大风）区分开。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a breeze、a light breeze。</li><li>熟词僻义：breeze through an exam 是&quot;轻松通过&quot;，不是&quot;吹着风考试&quot;。</li><li>拼写 breeze 双 e，不是 <s>breze</s>。</li></ul></div><div class="vocab-card"><h2 id="monsoon" tabindex="-1"><a class="header-anchor" href="#monsoon"><span>Monsoon</span></a></h2><p class="vc-meta"><strong>/mɒnˈsuːn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>季风；季风带来的雨季</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the monsoon season</td><td>季风季；雨季</td></tr><tr><td>monsoon rains</td><td>季风雨</td></tr><tr><td>the summer monsoon</td><td>夏季季风</td></tr><tr><td>a monsoon climate</td><td>季风气候</td></tr><tr><td>the arrival of the monsoon</td><td>季风的到来</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares monthly rainfall in a monsoon climate and a Mediterranean climate.</p><blockquote><p>该图比较了季风气候与地中海气候的月降水量。</p></blockquote><p><strong>Writing Task 2</strong> Agriculture in South Asia depends on the timing of the monsoon, which is becoming less predictable.</p><blockquote><p>南亚农业依赖季风到来的时间，而这一时间正变得越来越难预测。</p></blockquote><p><strong>Speaking</strong> We visited in June, right at the start of the monsoon, so it rained every afternoon.</p><blockquote><p>我们六月去的，正赶上季风开始，所以每天下午都下雨。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rainy season</td><td>雨季</td><td>只讲降水，不讲风向反转</td></tr><tr><td>trade wind</td><td>信风</td><td>常年风向稳定，不随季节反转</td></tr><tr><td>downpour</td><td>暴雨</td><td>指单次强降水</td></tr><tr><td>typhoon</td><td>台风</td><td>是风暴系统，不是风系</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 阿拉伯语 <em>mawsim</em>（季节）→ 葡萄牙语 <em>monção</em> → 英语 monsoon</li><li><strong>Family:</strong> monsoonal 季风的 / pre-monsoon 季风前的</li><li><strong>Memory Tip:</strong> mawsim 本义就是&quot;季节&quot;。季风是按季节整体反转的风系，所以这个词的字面意思就是&quot;季节风&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>通常带定冠词：the monsoon、the monsoon season。</li><li>作定语用单数：monsoon rains，不是 <s>monsoons rains</s>。</li><li>别与 typhoon 混：一个是季节性风系，一个是热带气旋。</li></ul></div><div class="vocab-card"><h2 id="gale" tabindex="-1"><a class="header-anchor" href="#gale"><span>Gale</span></a></h2><p class="vc-meta"><strong>/ɡeɪl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>大风（气象学上指八级风）；一阵（笑声）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>gale-force winds</td><td>八级大风</td></tr><tr><td>a gale warning</td><td>大风预警</td></tr><tr><td>gales of laughter</td><td>阵阵笑声</td></tr><tr><td>it blew a gale</td><td>刮起了大风</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows shipping routes affected by gale-force winds in winter.</p><blockquote><p>该地图显示了冬季受八级大风影响的航线。</p></blockquote><p><strong>Writing Task 2</strong> Coastal defences are designed to withstand gales that occur roughly once a decade.</p><blockquote><p>海岸防护设施按抵御约十年一遇的大风设计。</p></blockquote><p><strong>Speaking</strong> The ferry was cancelled because of gales, so we spent the day in the terminal.</p><blockquote><p>因为大风渡轮停航，我们在候船厅待了一天。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>storm</td><td>风暴</td><td>泛指恶劣天气，常伴随降水</td></tr><tr><td>hurricane</td><td>飓风</td><td>热带气旋，规模大得多</td></tr><tr><td>gust</td><td>阵风</td><td>短促的一阵，不持续</td></tr><tr><td>tempest</td><td>暴风雨</td><td>文学用语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古诺尔斯语 <em>galinn</em>（疯狂的）</li><li><strong>Family:</strong> gale-force 大风的 / gale warning 大风预警</li><li><strong>Memory Tip:</strong> gale 在气象学里有明确等级（八级，17.2–20.7 m/s）：比 storm 弱、比 gust 持久，是&quot;持续刮的大风&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作定语要加 -force：gale-force winds，不说 <s>gale winds</s>。</li><li>可数：a gale、gales。</li><li>gales of laughter 是固定搭配，指&quot;阵阵笑声&quot;。</li></ul></div><div class="vocab-card"><h2 id="hurricane" tabindex="-1"><a class="header-anchor" href="#hurricane"><span>Hurricane</span></a></h2><p class="vc-meta"><strong>/ˈhʌrɪkən/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>飓风（北大西洋与东北太平洋的热带气旋）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a hurricane warning</td><td>飓风预警</td></tr><tr><td>hurricane season</td><td>飓风季</td></tr><tr><td>hurricane-force winds</td><td>飓风级大风</td></tr><tr><td>the eye of the hurricane</td><td>飓风眼</td></tr><tr><td>a category 5 hurricane</td><td>五级飓风</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map tracks the path of a hurricane across the Caribbean.</p><blockquote><p>该地图追踪了一场飓风横穿加勒比海的路径。</p></blockquote><p><strong>Writing Task 2</strong> Warmer sea surfaces give hurricanes more energy, making them both stronger and wetter.</p><blockquote><p>更暖的海面为飓风提供更多能量，使其更强、带来更多降水。</p></blockquote><p><strong>Speaking</strong> We were evacuated twice during hurricane season — the second time we just stayed with friends inland.</p><blockquote><p>飓风季我们被疏散了两次，第二次干脆住到内地的朋友家。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>typhoon</td><td>台风</td><td>西北太平洋的同一现象</td></tr><tr><td>cyclone</td><td>气旋</td><td>印度洋与南太平洋的叫法</td></tr><tr><td>tornado</td><td>龙卷风</td><td>尺度小得多，多在陆地</td></tr><tr><td>storm</td><td>风暴</td><td>泛指，不分海域</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 西班牙语 <em>huracán</em>，源自泰诺语 <em>Hunraken</em>（风暴之神）</li><li><strong>Family:</strong> hurricane-force 飓风级的 / hurricane season 飓风季</li><li><strong>Memory Tip:</strong> 同一个东西三个名字，按海域分：大西洋叫 hurricane，西北太平洋叫 typhoon，印度洋叫 cyclone。记住这条，选择题就不会错。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>地区用词是考点：加勒比海、美国东岸用 hurricane。</li><li>固定搭配 the eye of the hurricane（飓风眼）。</li><li>可数：a hurricane、hurricanes。</li></ul></div><div class="vocab-card"><h2 id="tornado" tabindex="-1"><a class="header-anchor" href="#tornado"><span>Tornado</span></a></h2><p class="vc-meta"><strong>/tɔːˈneɪdəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>龙卷风（陆地上小尺度、漏斗状的强旋风）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a tornado warning</td><td>龙卷风预警</td></tr><tr><td>Tornado Alley</td><td>龙卷风走廊（美国中部）</td></tr><tr><td>a tornado touched down</td><td>龙卷风着陆</td></tr><tr><td>a funnel-shaped tornado</td><td>漏斗状龙卷风</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the frequency of tornadoes in the central United States.</p><blockquote><p>该地图显示了美国中部龙卷风的发生频率。</p></blockquote><p><strong>Writing Task 2</strong> Tornadoes are far smaller than hurricanes yet can destroy an entire town within minutes.</p><blockquote><p>龙卷风比飓风小得多，却能在几分钟内摧毁整个城镇。</p></blockquote><p><strong>Speaking</strong> We saw the sky turn green — that&#39;s when the tornado sirens started.</p><blockquote><p>我们看到天空变绿了，就在这时龙卷风警报响了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>twister</td><td>龙卷风</td><td>口语说法，新闻报道也用</td></tr><tr><td>whirlwind</td><td>旋风</td><td>泛指旋转的风，尺度可大可小</td></tr><tr><td>cyclone</td><td>气旋</td><td>大尺度天气系统</td></tr><tr><td>hurricane</td><td>飓风</td><td>直径数百公里，完全不同量级</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 西班牙语 <em>tronada</em>（雷暴）→ 英语误按 <em>tornar</em>（旋转）改成 tornado</li><li><strong>Family:</strong> tornadoes（复数）/ Tornado Alley 龙卷风走廊</li><li><strong>Memory Tip:</strong> 原名其实是&quot;雷暴&quot;，被英语按&quot;旋转&quot;改了拼写——一个以讹传讹却极其贴切的误读，因为龙卷风确实是旋转的。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数用 tornadoes，也可写 tornados。</li><li>与 hurricane 的量级差别是常识考点：龙卷风直径几十米到几百米。</li><li>拼写 tornado，不是 <s>tornato</s>。</li></ul></div><div class="vocab-card"><h2 id="typhoon" tabindex="-1"><a class="header-anchor" href="#typhoon"><span>Typhoon</span></a></h2><p class="vc-meta"><strong>/taɪˈfuːn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>台风（西北太平洋的热带气旋）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a typhoon warning</td><td>台风预警</td></tr><tr><td>typhoon season</td><td>台风季</td></tr><tr><td>a super typhoon</td><td>超强台风</td></tr><tr><td>the typhoon made landfall</td><td>台风登陆</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of typhoons making landfall in East Asia since 1990.</p><blockquote><p>该图显示了 1990 年以来登陆东亚的台风数量。</p></blockquote><p><strong>Writing Task 2</strong> Typhoons bring both destructive winds and the heavy rainfall that refills reservoirs.</p><blockquote><p>台风既带来破坏性大风，也带来重新蓄满水库的强降水。</p></blockquote><p><strong>Speaking</strong> In my city, typhoon days mean no school — we just sit and watch the rain come in sideways.</p><blockquote><p>在我家那边，台风天就停课，我们只是坐着看雨横着扫过来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hurricane</td><td>飓风</td><td>大西洋与东北太平洋的叫法</td></tr><tr><td>cyclone</td><td>气旋</td><td>印度洋与南太平洋的叫法</td></tr><tr><td>storm</td><td>风暴</td><td>泛指，不区分海域与强度</td></tr><tr><td>tempest</td><td>暴风雨</td><td>文学用语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 一说源自希腊语 <em>typhon</em>（旋风），一说源自汉语&quot;台风&quot;的音译，两说并存</li><li><strong>Family:</strong> typhoon season 台风季 / super typhoon 超强台风</li><li><strong>Memory Tip:</strong> 广东话&quot;大风&quot;（tai fung）与希腊语 typhon 撞在一起，词源至今无定论——但记&quot;西北太平洋的飓风叫台风&quot;这一条就够了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>按海域用词：中国、日本、菲律宾一带用 typhoon。</li><li>不用冠词泛指：Typhoons are common here；特指某次才用 the。</li><li>拼写 typhoon 中间是 -ph-，不是 <s>tiphoon</s>。</li></ul></div><div class="vocab-card"><h2 id="blow" tabindex="-1"><a class="header-anchor" href="#blow"><span>Blow</span></a></h2><p class="vc-meta"><strong>/bləʊ/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：（风）吹；吹动；爆炸（blow up）；（轮胎）爆裂</li><li>名词：打击，挫折</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the wind blows</td><td>刮风</td></tr><tr><td>blow away</td><td>吹走</td></tr><tr><td>blow up</td><td>爆炸；充气；放大</td></tr><tr><td>blow out</td><td>吹灭</td></tr><tr><td>a heavy blow</td><td>沉重的打击</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows prevailing winds blowing from the west.</p><blockquote><p>该地图显示了自西向东的盛行风。</p></blockquote><p><strong>Writing Task 2</strong> Winds blow harder across open water than over land because there is less friction.</p><blockquote><p>开阔水面上风的强度大于陆地，因为摩擦力更小。</p></blockquote><p><strong>Speaking</strong> The wind was blowing so hard that my umbrella turned inside out.</p><blockquote><p>风大得把伞都吹翻了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gust</td><td>阵风</td><td>名词，指突然的一阵</td></tr><tr><td>sweep</td><td>掠过</td><td>强调横扫的范围</td></tr><tr><td>waft</td><td>飘送</td><td>轻柔地飘，多指气味</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>blāwan</em>，与拉丁 <em>flare</em>（吹）同源</li><li><strong>Family:</strong> blow 吹 / blower 鼓风机 / blow-up 爆炸；放大 / blowing 吹着的</li><li><strong>Memory Tip:</strong> 三条线：风吹（the wind blows）、打击（a heavy blow）、爆炸（blow up）。blow hot and cold 是&quot;反复无常&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不规则变化：blow - blew - blown。</li><li>&quot;刮起来&quot;是 the wind got up / blew up，而 blow up 更多指&quot;爆炸&quot;。</li><li>a heavy blow 是比喻&quot;沉重打击&quot;，不是&quot;大风&quot;。</li></ul></div><div class="vocab-card"><h2 id="puff" tabindex="-1"><a class="header-anchor" href="#puff"><span>Puff</span></a></h2><p class="vc-meta"><strong>/pʌf/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：（一）喷，（一）股（烟、气）；喘息</li><li>动词：喷出；喘气；一口口地抽</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a puff of smoke</td><td>一股烟</td></tr><tr><td>a puff of wind</td><td>一阵风</td></tr><tr><td>out of puff</td><td>喘不上气（英式口语）</td></tr><tr><td>huff and puff</td><td>气喘吁吁；愤愤不平</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows puffs of steam rising from the cooling towers.</p><blockquote><p>该示意图显示了冷却塔冒出的团团蒸汽。</p></blockquote><p><strong>Writing Task 2</strong> Every puff of exhaust adds particulates to the air we breathe.</p><blockquote><p>每一股尾气都在为我们呼吸的空气增加颗粒物。</p></blockquote><p><strong>Speaking</strong> I was out of puff after two flights of stairs.</p><blockquote><p>爬了两层楼我就喘不上气了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gust</td><td>一阵（风）</td><td>专指风，强度更大</td></tr><tr><td>whiff</td><td>一丝（气味）</td><td>强调气味的一缕</td></tr><tr><td>blast</td><td>一股（气流）</td><td>强调冲击力</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拟声词，模拟吹气的声音</li><li><strong>Family:</strong> puff 喷 / puffy 肿胀的 / cream puff 奶油泡芙 / powder puff 粉扑</li><li><strong>Memory Tip:</strong> 核心语义是&quot;一小团、一下&quot;：a puff of smoke（一股烟）、a puff of wind（一阵风）。 puff pastry 是&quot;起酥点心&quot;，也是&quot;膨胀&quot;的意思。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>结构是 a puff of + 不可数名词（smoke / wind）。</li><li>out of puff 是英式口语&quot;喘不上气&quot;，不用于正式写作。</li><li>puffy 表&quot;肿的、松软的&quot;，与 puff 词性不同。</li></ul></div><div class="vocab-card"><h2 id="gush" tabindex="-1"><a class="header-anchor" href="#gush"><span>Gush</span></a></h2><p class="vc-meta"><strong>/ɡʌʃ/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：（液体）涌出，喷出；滔滔不绝地说</li><li>名词：涌流；迸发</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>water gushed out</td><td>水喷涌而出</td></tr><tr><td>gush from</td><td>从……涌出</td></tr><tr><td>a gush of</td><td>一股（涌流）</td></tr><tr><td>gushing praise</td><td>过分的赞美</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows water gushing from a burst pipe.</p><blockquote><p>该示意图显示了水从破裂管道中喷涌而出。</p></blockquote><p><strong>Writing Task 2</strong> Oil gushed into the sea for weeks before the well was finally capped.</p><blockquote><p>石油喷入海中数周，油井才最终被封堵。</p></blockquote><p><strong>Speaking</strong> Blood was gushing from the cut, so we went straight to hospital.</p><blockquote><p>伤口血流不止，我们直接去了医院。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>spurt</td><td>喷射</td><td>短促有力，量小</td></tr><tr><td>pour</td><td>倾泻</td><td>强调连续大量</td></tr><tr><td>spout</td><td>喷出</td><td>多指从孔口喷出</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>guschen</em>（涌出）</li><li><strong>Family:</strong> gush 涌出 / gushing 涌流的；过分热情的 / a gusher 喷油井</li><li><strong>Memory Tip:</strong> 强调&quot;量大且突然&quot;——water gushed out。引申到说话就是&quot;滔滔不绝&quot;，gushing praise 带点贬义（过度热情）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 from 或 out of。</li><li>gushing 形容人时带贬义，别用来夸人热情。</li><li>拼写 gush，别与 gash（深伤口）混。</li></ul></div><div class="vocab-card"><h2 id="thunder" tabindex="-1"><a class="header-anchor" href="#thunder"><span>Thunder</span></a></h2><p class="vc-meta"><strong>/ˈθʌndə(r)/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：雷，雷声</li><li>动词：打雷；轰隆作响</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>thunder and lightning</td><td>雷电</td></tr><tr><td>a clap of thunder</td><td>一声雷</td></tr><tr><td>a thunder storm</td><td>雷暴</td></tr><tr><td>thunder rolls</td><td>雷声隆隆</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the average number of thunder days recorded each year.</p><blockquote><p>该图表显示了每年记录到的平均雷暴日数。</p></blockquote><p><strong>Writing Task 2</strong> Warmer air holds more moisture, which is why thunder storms are becoming more intense.</p><blockquote><p>更暖的空气能容纳更多水汽，这正是雷暴变得更猛烈的原因。</p></blockquote><p><strong>Speaking</strong> The thunder woke me at three in the morning.</p><blockquote><p>凌晨三点我被雷声吵醒。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rumble</td><td>隆隆声</td><td>形容持续低沉的声响</td></tr><tr><td>roar</td><td>轰鸣</td><td>声音更大更持续</td></tr><tr><td>boom</td><td>轰响</td><td>短促而有回响</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>thunor</em>，与拉丁 <em>tonare</em>（打雷）同源</li><li><strong>Family:</strong> thunder 雷 / thunderstorm 雷暴 / thunderous 雷鸣般的 / Thursday 星期四</li><li><strong>Memory Tip:</strong> Thursday 就是&quot;雷神托尔之日&quot;（Thor&#39;s day），与 thunder 同源。英语的星期几乎全是神名，顺着这条线能记一串。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a thunder</s>；可说 a clap of thunder。</li><li>&quot;打雷了&quot;说 it thundered / there was thunder。</li><li>thunderstorm 写成一个词，不拆分。</li></ul></div><div class="vocab-card"><h2 id="lightning" tabindex="-1"><a class="header-anchor" href="#lightning"><span>Lightning</span></a></h2><p class="vc-meta"><strong>/ˈlaɪtnɪŋ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>闪电，雷电</li><li>（作定语）闪电般的，极快的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a flash of lightning</td><td>一道闪电</td></tr><tr><td>a lightning strike</td><td>雷击</td></tr><tr><td>at lightning speed</td><td>以闪电般的速度</td></tr><tr><td>a lightning rod</td><td>避雷针</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the frequency of lightning strikes across the region.</p><blockquote><p>该地图显示了该地区雷击的发生频率。</p></blockquote><p><strong>Writing Task 2</strong> A single lightning strike can start a wildfire that burns for weeks.</p><blockquote><p>一次雷击就能引发一场烧上数周的野火。</p></blockquote><p><strong>Speaking</strong> We counted the seconds between the flash and the thunder to judge the distance.</p><blockquote><p>我们数着闪电和雷声之间的秒数来判断距离。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>flash</td><td>闪光</td><td>指那道亮光，非放电现象</td></tr><tr><td>bolt</td><td>闪电</td><td>一道竖直的闪电</td></tr><tr><td>thunderbolt</td><td>霹雳</td><td>文学化，常带&quot;突降灾祸&quot;意味</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>līhting</em> ← <em>līht</em>（光、明亮），与 <em>light</em> 同源</li><li><strong>Family:</strong> lightning 闪电 / lighten 使明亮；打闪 / lightning-fast 极快的</li><li><strong>Memory Tip:</strong> 记一句就够：<strong>闪电没有 e</strong>。lightning 是闪电，lightening 是&quot;变亮／减轻&quot;——少一个字母，意思全变。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 lightning，写成 lightening 就变成&quot;变亮／减轻&quot;了。</li><li>不可数：不说 <s>a lightning</s>，要说 a flash of lightning。</li><li>lightning 是名词，修饰名词时可作定语：a lightning strike。</li></ul></div><div class="vocab-card"><h2 id="stormy" tabindex="-1"><a class="header-anchor" href="#stormy"><span>Stormy</span></a></h2><p class="vc-meta"><strong>/ˈstɔːmi/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>暴风雨的，有风暴的</li><li>激烈的，争吵不断的（会议、关系）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>stormy weather</td><td>暴风雨天气</td></tr><tr><td>a stormy sea</td><td>波涛汹涌的海面</td></tr><tr><td>a stormy meeting</td><td>争论激烈的会议</td></tr><tr><td>storm surge</td><td>风暴潮</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of stormy days recorded at the station.</p><blockquote><p>该图表显示了该站记录到的暴风雨天数。</p></blockquote><p><strong>Writing Task 2</strong> Stormy weather is delaying shipping along the coast and pushing up insurance costs.</p><blockquote><p>暴风雨天气正延误沿海航运，并推高保险成本。</p></blockquote><p><strong>Speaking</strong> The crossing was stormy, and most people stayed in their cabins.</p><blockquote><p>这趟渡海风浪很大，大多数人留在舱里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rough</td><td>风浪大的</td><td>多形容海面，程度可轻可重</td></tr><tr><td>tempestuous</td><td>狂暴的</td><td>书面，文学化</td></tr><tr><td>turbulent</td><td>动荡的</td><td>多用于气流、局势</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>storm</em>（暴风雨）+ <em>-y</em></li><li><strong>Family:</strong> storm 暴风雨 / stormy 暴风雨的 / storm surge 风暴潮 / brainstorm 头脑风暴</li><li><strong>Memory Tip:</strong> 两条线：天气（a stormy sea）与人事（a stormy meeting 争论激烈）。storm surge（风暴潮）是地理与灾害话题的高频术语。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词 stormy、名词 storm，别混用。</li><li>&quot;风暴潮&quot;是 storm surge，是专业术语。</li><li>比较级 stormier，最高级 stormiest。</li></ul></div><div class="vocab-card"><h2 id="downpour" tabindex="-1"><a class="header-anchor" href="#downpour"><span>Downpour</span></a></h2><p class="vc-meta"><strong>/ˈdaʊnpɔː(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>倾盆大雨，暴雨</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a sudden downpour</td><td>骤降的暴雨</td></tr><tr><td>be caught in a downpour</td><td>被暴雨淋到</td></tr><tr><td>torrential downpour</td><td>倾盆大雨</td></tr><tr><td>a heavy downpour</td><td>一场大雨</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows that August had the heaviest downpours of the year.</p><blockquote><p>该图表显示八月的暴雨是全年最强的。</p></blockquote><p><strong>Writing Task 2</strong> Sudden downpours overwhelm drainage systems that were built for a drier climate.</p><blockquote><p>骤降的暴雨让按更干燥气候设计的排水系统无力承受。</p></blockquote><p><strong>Speaking</strong> We got caught in a downpour and were soaked within seconds.</p><blockquote><p>我们遇上暴雨，几秒钟就湿透了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>deluge</td><td>暴雨；洪水</td><td>规模更大，常带灾害意味</td></tr><tr><td>cloudburst</td><td>骤雨</td><td>气象术语，短时极强</td></tr><tr><td>torrential rain</td><td>倾盆大雨</td><td>描述性短语，非单个名词</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>down</em>（向下）+ <em>pour</em>（倒、倾泻）</li><li><strong>Family:</strong> downpour 暴雨 / pour 倾泻 / pouring 倾盆的 / downpipe 落水管</li><li><strong>Memory Tip:</strong> down + pour = &quot;往下倒&quot;。口语说 it&#39;s pouring 就是&quot;正下大雨&quot;。与 rainfall（雨量）不同，downpour 强调&quot;一次猛下&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a downpour / heavy downpours；rain 则不可数。</li><li>&quot;被雨淋到&quot;用 be caught in a downpour。</li><li>pour 是动词，downpour 才是名词。</li></ul></div><div class="vocab-card"><h2 id="rainfall" tabindex="-1"><a class="header-anchor" href="#rainfall"><span>Rainfall</span></a></h2><p class="vc-meta"><strong>/ˈreɪnfɔːl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>降雨；降雨量（不可数）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>annual rainfall</td><td>年降雨量</td></tr><tr><td>heavy rainfall</td><td>强降雨</td></tr><tr><td>low rainfall</td><td>降水稀少</td></tr><tr><td>rainfall pattern</td><td>降水格局</td></tr><tr><td>average rainfall</td><td>平均降雨量</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares average annual rainfall in four cities.</p><blockquote><p>该图表比较了四个城市的年平均降雨量。</p></blockquote><p><strong>Writing Task 2</strong> Changing rainfall patterns are making farming less predictable in many regions.</p><blockquote><p>降水格局的变化正让许多地区的农业变得更难预测。</p></blockquote><p><strong>Speaking</strong> This area gets very little rainfall — under 200 millimetres a year.</p><blockquote><p>这一带降雨极少，一年不到两百毫米。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>precipitation</td><td>降水</td><td>含雨、雪、冰雹，学术用语</td></tr><tr><td>rain</td><td>雨</td><td>日常词，不可数</td></tr><tr><td>moisture</td><td>水分</td><td>泛指含水量，非降水量</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>rain</em>（雨）+ <em>fall</em>（降落）</li><li><strong>Family:</strong> rainfall 降雨量 / rain 雨 / rainforest 雨林 / rain gauge 雨量计</li><li><strong>Memory Tip:</strong> 图表题必备三件套：annual / average / monthly rainfall，单位是 millimetres。要更学术就换 precipitation，它把雪和冰雹也算进去。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a rainfall</s>；说 the amount of rainfall。</li><li>量词用 high / low / heavy，不用 <s>big</s>。</li><li>precipitation 比 rainfall 更学术，二者不可随意互换（前者含雪）。</li></ul></div><div class="vocab-card"><h2 id="sprinkle" tabindex="-1"><a class="header-anchor" href="#sprinkle"><span>Sprinkle</span></a></h2><p class="vc-meta"><strong>/ˈsprɪŋkl/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：撒，洒；下小雨</li><li>名词：少量，一点点；（美式）小雨</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>sprinkle water on</td><td>在……上洒水</td></tr><tr><td>sprinkle with salt</td><td>撒上盐</td></tr><tr><td>a sprinkle of rain</td><td>一点小雨</td></tr><tr><td>sprinkler irrigation</td><td>喷灌</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows sprinkler irrigation covering the eastern fields.</p><blockquote><p>该地图显示了覆盖东部农田的喷灌系统。</p></blockquote><p><strong>Writing Task 2</strong> Farmers sprinkle water onto seedlings during the driest weeks of the season.</p><blockquote><p>在一年中最干旱的几周里，农民会给幼苗洒水。</p></blockquote><p><strong>Speaking</strong> It&#39;s only sprinkling — you don&#39;t need an umbrella.</p><blockquote><p>只是毛毛雨，不用打伞。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>scatter</td><td>撒</td><td>强调分散抛撒，颗粒更大</td></tr><tr><td>drizzle</td><td>下毛毛雨</td><td>只对应&quot;小雨&quot;义</td></tr><tr><td>spray</td><td>喷洒</td><td>用器具喷，非手撒</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>sprenklen</em>，与&quot;散开、点滴&quot;的语感相关</li><li><strong>Family:</strong> sprinkle 撒；小雨 / sprinkler 洒水器 / sprinkling 少量</li><li><strong>Memory Tip:</strong> 两个场景一起记：撒东西（sprinkle salt on chips）、下小雨（it&#39;s sprinkling）。名词 a sprinkle of 就是&quot;一点点&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>两种搭配：sprinkle A on B / sprinkle B with A。</li><li>sprinkler 是&quot;洒水器&quot;，不是&quot;小雨&quot;。</li><li>表示&quot;毛毛雨&quot;更常说 drizzle，sprinkle 偏美式口语。</li></ul></div><div class="vocab-card"><h2 id="rainbow" tabindex="-1"><a class="header-anchor" href="#rainbow"><span>Rainbow</span></a></h2><p class="vc-meta"><strong>/ˈreɪnbəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>彩虹</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a rainbow appears</td><td>出现彩虹</td></tr><tr><td>a double rainbow</td><td>双彩虹</td></tr><tr><td>at the end of the rainbow</td><td>遥不可及的美好</td></tr><tr><td>rainbow-coloured</td><td>彩虹色的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a rainbow forming over the valley after the storm.</p><blockquote><p>照片显示了暴风雨后山谷上空形成的彩虹。</p></blockquote><p><strong>Writing Task 2</strong> Rainbows form when sunlight is refracted and reflected inside water droplets.</p><blockquote><p>彩虹形成于阳光在水滴内部发生折射与反射的过程。</p></blockquote><p><strong>Speaking</strong> There was a full rainbow over the harbour — you could see both ends.</p><blockquote><p>港口上空出现了一道完整的彩虹，两端都看得见。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>arc</td><td>弧</td><td>描述形状，非气象现象</td></tr><tr><td>spectrum</td><td>光谱</td><td>指分光后的色带</td></tr><tr><td>prism effect</td><td>棱镜效应</td><td>解释成因，非名词替换</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>rain</em>（雨）+ <em>bow</em>（弓形）</li><li><strong>Family:</strong> rainbow 彩虹 / bow 弓；鞠躬 / rainbow trout 虹鳟</li><li><strong>Memory Tip:</strong> bow = 弓，彩虹就是&quot;雨做的一张弓&quot;。at the end of the rainbow 指&quot;遥不可及的美好愿景&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a rainbow / rainbows。</li><li>写成一个词，不加连字符。</li><li>&quot;双彩虹&quot;是 a double rainbow。</li></ul></div><div class="vocab-card"><h2 id="shower" tabindex="-1"><a class="header-anchor" href="#shower"><span>Shower</span></a></h2><p class="vc-meta"><strong>/ˈʃaʊə(r)/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：阵雨；淋浴；一阵（礼物、掌声等）</li><li>动词：淋浴；大量给予</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a rain shower</td><td>一阵雨</td></tr><tr><td>scattered showers</td><td>零星阵雨</td></tr><tr><td>take a shower</td><td>洗淋浴</td></tr><tr><td>a shower of</td><td>一阵（掌声、礼物）</td></tr><tr><td>shower gel</td><td>沐浴露</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The forecast shows scattered showers across the west in the afternoon.</p><blockquote><p>预报显示下午西部有零星阵雨。</p></blockquote><p><strong>Writing Task 2</strong> Brief showers do little for crops once the soil has dried out.</p><blockquote><p>土壤一旦干透，短暂的阵雨对作物几乎无用。</p></blockquote><p><strong>Speaking</strong> I got caught in a shower on the way home and had to change.</p><blockquote><p>回家路上被一阵雨淋了，只好换衣服。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>downpour</td><td>暴雨</td><td>强度大得多</td></tr><tr><td>drizzle</td><td>毛毛雨</td><td>极细密、持续</td></tr><tr><td>sprinkle</td><td>小雨</td><td>美式口语，程度最轻</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>scūr</em>（阵雨、急降）</li><li><strong>Family:</strong> shower 阵雨；淋浴 / showery 阵雨的 / rain shower 花洒 / shower gel 沐浴露</li><li><strong>Memory Tip:</strong> 核心语义是&quot;一阵一阵地来&quot;：a shower of rain（阵雨）、a shower of gifts（一阵礼物雨）、take a shower（冲个澡）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a shower / scattered showers。</li><li>洗澡英式说 have a shower，美式说 take a shower。</li><li>天气预报固定搭配 scattered showers（零星阵雨）。</li></ul></div><div class="vocab-card"><h2 id="smog" tabindex="-1"><a class="header-anchor" href="#smog"><span>Smog</span></a></h2><p class="vc-meta"><strong>/smɒɡ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>烟雾，雾霾（烟与雾混合的污染空气）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>photochemical smog</td><td>光化学烟雾</td></tr><tr><td>thick smog</td><td>浓重雾霾</td></tr><tr><td>smog levels</td><td>雾霾浓度</td></tr><tr><td>a smog alert</td><td>雾霾预警</td></tr><tr><td>reduce smog</td><td>减少雾霾</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart tracks average smog levels in four major cities over ten years.</p><blockquote><p>该图追踪了四个大城市十年间的平均雾霾浓度。</p></blockquote><p><strong>Writing Task 2</strong> Photochemical smog forms when traffic emissions react with sunlight on still, hot days.</p><blockquote><p>光化学烟雾在无风炎热的天气里，由交通尾气与阳光反应生成。</p></blockquote><p><strong>Speaking</strong> On bad smog days you can&#39;t see the hills at the edge of the city at all.</p><blockquote><p>雾霾严重的时候，城市边缘的山一点都看不见。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>haze</td><td>霾</td><td>更偏气象描述，成因可含尘与烟</td></tr><tr><td>fog</td><td>雾</td><td>纯水汽，不含污染</td></tr><tr><td>air pollution</td><td>空气污染</td><td>上位概念，含颗粒物、气体等</td></tr><tr><td>smoke</td><td>烟</td><td>燃烧产生的可见气体</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> smoke + fog 的混成词（portmanteau），1905 年伦敦报纸首创</li><li><strong>Family:</strong> smoggy 雾霾的 / smog alert 雾霾预警</li><li><strong>Memory Tip:</strong> 把 smoke 的头和 fog 的尾拼起来就是 smog。同类拼合词还有 brunch（breakfast + lunch）、motel（motor + hotel）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>a smog</s> ✘；说 heavy smog。</li><li>与 fog 区分：fog 是水汽，smog 是污染——这是环境类写作的常识点。</li><li>拼写 smog，不是 <s>smogg</s>。</li></ul></div><div class="vocab-card"><h2 id="fume" tabindex="-1"><a class="header-anchor" href="#fume"><span>Fume</span></a></h2><p class="vc-meta"><strong>/fjuːm/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词（常用复数）：（有害的）烟、气</li><li>动词：冒烟；发怒，恼火</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>toxic fumes</td><td>有毒气体</td></tr><tr><td>exhaust fumes</td><td>汽车尾气</td></tr><tr><td>fumes from paint</td><td>油漆挥发的气体</td></tr><tr><td>fume over / about</td><td>对……恼火</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how exhaust fumes are trapped in the valley during a temperature inversion.</p><blockquote><p>该图显示了逆温期间汽车尾气如何被困在山谷中。</p></blockquote><p><strong>Writing Task 2</strong> Workers exposed to chemical fumes face a higher risk of long-term lung damage.</p><blockquote><p>长期接触化学气体的工人面临更高的慢性肺损伤风险。</p></blockquote><p><strong>Speaking</strong> The smell of paint fumes gave me a headache for the whole afternoon.</p><blockquote><p>油漆味让我整个下午都头疼。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>vapour</td><td>蒸汽</td><td>多为无害的液体蒸气</td></tr><tr><td>smoke</td><td>烟</td><td>燃烧产生的可见颗粒</td></tr><tr><td>gas</td><td>气体</td><td>中性，不含&quot;有害&quot;意味</td></tr><tr><td>exhaust</td><td>废气</td><td>特指机器排出的</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>fumus</em>（烟）</li><li><strong>Family:</strong> perfume 香水（per- 透过 + fume，原义&quot;透过烟飘来的香气&quot;）/ fumigate 熏蒸</li><li><strong>Memory Tip:</strong> fumus 是烟。perfume 字面是&quot;穿过烟雾飘来的气味&quot;，fumigate 是&quot;用烟熏&quot;。都是同一个烟。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>表有害气体时多用复数：toxic fumes、 exhaust fumes。</li><li>动词 fume 表&quot;恼火&quot;是口语用法，正式写作里少用。</li><li>别与 perfume（香水）混义，虽然同源。</li></ul></div><div class="vocab-card"><h2 id="mist" tabindex="-1"><a class="header-anchor" href="#mist"><span>Mist</span></a></h2><p class="vc-meta"><strong>/mɪst/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：薄雾，轻雾；水汽形成的雾气</li><li>动词：起雾；（镜片等）蒙上水汽</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>morning mist</td><td>晨雾</td></tr><tr><td>a veil of mist</td><td>一层薄雾</td></tr><tr><td>mist over</td><td>起雾；变得模糊</td></tr><tr><td>the windows misted up</td><td>窗户蒙上水汽</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows morning mist lying in the valley below the ridge.</p><blockquote><p>照片显示了山脊下方山谷中滞留的晨雾。</p></blockquote><p><strong>Writing Task 2</strong> Coastal mist, formed when warm air passes over cold water, is a reliable source of water in some dry regions.</p><blockquote><p>暖空气经过冷水时形成的沿海薄雾，是一些干旱地区稳定的水源。</p></blockquote><p><strong>Speaking</strong> We set off before dawn and the fields were covered in mist.</p><blockquote><p>我们天亮前出发，田野上笼着一层薄雾。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fog</td><td>雾</td><td>更浓，能见度更低</td></tr><tr><td>haze</td><td>霾</td><td>偏干性，多含尘或污染物</td></tr><tr><td>vapour</td><td>水汽</td><td>气态水，不一定是可见雾</td></tr><tr><td>drizzle</td><td>毛毛雨</td><td>是降水，不是悬浮水汽</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>mist</em>（雾），与 misty、mist over 同源</li><li><strong>Family:</strong> misty 有薄雾的 / mist over 起雾 / mist up （镜片）蒙雾</li><li><strong>Memory Tip:</strong> 按浓度排一条线：<strong>mist（薄）&lt; fog（浓）&lt; 能见度不足 1 公里在气象上就叫 fog</strong>。写作里形容&quot;仙境感&quot;用 mist，形容&quot;航班延误&quot;用 fog。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>a mist</s> ✘；要说 a veil of mist。</li><li>与 fog 的浓度差别是地理描述的关键，别随手互换。</li><li>动词 mist up 多用于镜片、玻璃：The mirror misted up。</li></ul></div><div class="vocab-card"><h2 id="vapour" tabindex="-1"><a class="header-anchor" href="#vapour"><span>Vapour</span></a></h2><p class="vc-meta"><strong>/ˈveɪpə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>水汽，蒸汽（气态的水或液体）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>water vapour</td><td>水汽</td></tr><tr><td>vapour pressure</td><td>水汽压</td></tr><tr><td>a vapour trail</td><td>凝结尾迹</td></tr><tr><td>condense from vapour</td><td>由水汽凝结</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows water vapour rising from the ocean surface.</p><blockquote><p>该示意图显示了水汽从洋面上升的过程。</p></blockquote><p><strong>Writing Task 2</strong> Warmer air can hold more water vapour, which intensifies heavy rainfall.</p><blockquote><p>更暖的空气能容纳更多水汽，从而使强降雨更为猛烈。</p></blockquote><p><strong>Speaking</strong> You can see the vapour when you breathe out on a cold day.</p><blockquote><p>冷天呼气时能看到水汽。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>steam</td><td>蒸汽</td><td>指可见的白色蒸汽</td></tr><tr><td>mist</td><td>薄雾</td><td>已凝结成小水滴</td></tr><tr><td>gas</td><td>气体</td><td>泛指，非水汽专称</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>vapor</em>（蒸气）</li><li><strong>Family:</strong> vapour 水汽 / vaporise 汽化 / vaporous 雾状的 / evaporation 蒸发</li><li><strong>Memory Tip:</strong> water vapour 是看不见的气态水，steam 是看得见的白汽。水循环里它是最先出场的那一环。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a vapour</s>。</li><li>英式拼写 vapour，美式 vapor，全篇统一。</li><li>与 steam 的可见性差异是科学描述的关键。</li></ul></div><div class="vocab-card"><h2 id="evaporate" tabindex="-1"><a class="header-anchor" href="#evaporate"><span>Evaporate</span></a></h2><p class="vc-meta"><strong>/ɪˈvæpəreɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>蒸发，汽化</li><li>消失，消散（希望、资金等）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>water evaporates</td><td>水蒸发</td></tr><tr><td>evaporate from</td><td>从……蒸发</td></tr><tr><td>evaporation rate</td><td>蒸发速率</td></tr><tr><td>evaporate into</td><td>蒸发成</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows evaporation rates peaking in midsummer.</p><blockquote><p>该图表显示蒸发速率在盛夏达到峰值。</p></blockquote><p><strong>Writing Task 2</strong> As temperatures rise, more water evaporates and soils dry out faster.</p><blockquote><p>随着气温上升，更多水分蒸发，土壤干得更快。</p></blockquote><p><strong>Speaking</strong> The puddle evaporated in the afternoon sun.</p><blockquote><p>水洼在午后阳光下蒸发了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dry up</td><td>干涸</td><td>强调结果，多指水源</td></tr><tr><td>vaporise</td><td>汽化</td><td>技术用语，含沸腾</td></tr><tr><td>dissipate</td><td>消散</td><td>多用于雾气、情绪</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>e-</em>（出）+ 拉丁 <em>vapor</em>（汽）→ &quot;变成汽跑掉&quot;</li><li><strong>Family:</strong> evaporate 蒸发 / evaporation 蒸发 / evaporative 蒸发的</li><li><strong>Memory Tip:</strong> 水循环三段：evaporation 蒸发 → condensation 凝结 → precipitation 降水。三个词连起来就是一张流程图。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>多为不及物：water evaporates。</li><li>名词是 evaporation，不是 <s>evaporment</s>。</li><li>vaporise 偏技术（含沸腾汽化），日常蒸发用 evaporate。</li></ul></div><div class="vocab-card"><h2 id="circulate" tabindex="-1"><a class="header-anchor" href="#circulate"><span>Circulate</span></a></h2><p class="vc-meta"><strong>/ˈsɜːkjəleɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>循环，环流</li><li>流通，传播（信息、货币）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>ocean circulation</td><td>海洋环流</td></tr><tr><td>air circulates</td><td>空气流通</td></tr><tr><td>circulate a document</td><td>传阅文件</td></tr><tr><td>blood circulation</td><td>血液循环</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how water circulates between the ocean and the atmosphere.</p><blockquote><p>该示意图显示了水在海洋与大气之间循环的过程。</p></blockquote><p><strong>Writing Task 2</strong> Ocean circulation redistributes heat from the tropics towards the poles.</p><blockquote><p>海洋环流把热量从热带重新分配到两极。</p></blockquote><p><strong>Speaking</strong> Open a window so the air can circulate.</p><blockquote><p>开扇窗，让空气流通一下。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>flow</td><td>流动</td><td>单向流动，非闭合回路</td></tr><tr><td>cycle</td><td>循环</td><td>名词更常用：water cycle</td></tr><tr><td>distribute</td><td>分发</td><td>只对应&quot;传播&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>circulus</em>（小环）← <em>circus</em>（圆圈）</li><li><strong>Family:</strong> circulate 循环 / circulation 循环；发行量 / circular 圆形的；传阅的</li><li><strong>Memory Tip:</strong> circulus = 小圈，所以 circulate 是&quot;绕着圈走&quot;。注意：水循环是 water cycle，海洋环流才是 ocean circulation。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物、不及物都可用：circulate a memo / blood circulates。</li><li>名词是 circulation（循环；发行量）。</li><li>&quot;水循环&quot;用 water cycle，不用 <s>water circulation</s>。</li></ul></div><div class="vocab-card"><h2 id="precipitate" tabindex="-1"><a class="header-anchor" href="#precipitate"><span>Precipitate</span></a></h2><p class="vc-meta"><strong>/prɪˈsɪpɪteɪt/</strong> · verb · 动词（名词与形容词读 /prɪˈsɪpɪtət/）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：使（事件）突然发生，加速</li><li>动词：（使）降水；（使）沉淀</li><li>名词：沉淀物／形容词：仓促的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>precipitate a crisis</td><td>引发危机</td></tr><tr><td>precipitation</td><td>降水（名词）</td></tr><tr><td>precipitate a decline</td><td>加速衰退</td></tr><tr><td>a precipitate decision</td><td>仓促的决定</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows annual precipitation in millimetres across four regions.</p><blockquote><p>该图表显示了四个地区的年降水量（毫米）。</p></blockquote><p><strong>Writing Task 2</strong> Drought can precipitate a sudden food crisis in import-dependent countries.</p><blockquote><p>干旱可能在依赖进口的国家引发突发的粮食危机。</p></blockquote><p><strong>Speaking</strong> The announcement precipitated a rush on the banks.</p><blockquote><p>那项公告引发了银行挤兑。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>trigger</td><td>引发</td><td>最常用，中性</td></tr><tr><td>hasten</td><td>加速</td><td>强调使提前发生</td></tr><tr><td>bring about</td><td>导致</td><td>口语化，因果更间接</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>prae-</em>（前）+ <em>caput</em>（头）→ &quot;头朝下坠落&quot;</li><li><strong>Family:</strong> precipitate 使突然发生 / precipitation 降水；沉淀 / precipitous 陡峭的；仓促的</li><li><strong>Memory Tip:</strong> 气象里的&quot;降水&quot;是名词 precipitation（含雨、雪、雹），动词 precipitate 则表&quot;使突然发生&quot;。同一个词根，两个领域各取一义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>气象&quot;降水&quot;固定用名词 precipitation。</li><li>动词义偏正式，口语多用 trigger / cause。</li><li>precipitous 是形容词&quot;陡峭的、仓促的&quot;，与 precipitate 别混。</li></ul></div><div class="vocab-card"><h2 id="dew" tabindex="-1"><a class="header-anchor" href="#dew"><span>Dew</span></a></h2><p class="vc-meta"><strong>/djuː/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>露，露水</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>morning dew</td><td>晨露</td></tr><tr><td>the dew point</td><td>露点</td></tr><tr><td>dew forms</td><td>结露</td></tr><tr><td>wet with dew</td><td>被露水打湿</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows dew point temperatures recorded at dawn.</p><blockquote><p>该图表显示了黎明时分记录的露点温度。</p></blockquote><p><strong>Writing Task 2</strong> Dew forms when surfaces cool below the dew point overnight.</p><blockquote><p>夜间地表温度降到露点以下时就会结露。</p></blockquote><p><strong>Speaking</strong> The grass was wet with dew when we set off.</p><blockquote><p>我们出发时草地上满是露水。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>condensation</td><td>凝结水</td><td>更技术，含结露与结霜</td></tr><tr><td>moisture</td><td>水汽</td><td>泛指含水量</td></tr><tr><td>drizzle</td><td>毛毛雨</td><td>是降水，不是凝结</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>dēaw</em>（露）</li><li><strong>Family:</strong> dew 露水 / dewy 沾露的 / dew point 露点</li><li><strong>Memory Tip:</strong> dew point（露点）是气象核心概念：气温降到露点，水汽便凝结成露。这一句能把&quot;露&quot;和&quot;凝结&quot;两个概念串起来。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a dew</s>。</li><li>dew point 是固定术语，不用 <s>dew temperature</s>。</li><li>与 due（到期的）同音不同形，别写错。</li></ul></div><div class="vocab-card"><h2 id="dense" tabindex="-1"><a class="header-anchor" href="#dense"><span>Dense</span></a></h2><p class="vc-meta"><strong>/dens/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>密集的，稠密的</li><li>浓的（雾、烟）；（物质）密度大的</li><li>（口语）愚钝的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>dense forest</td><td>茂密的森林</td></tr><tr><td>densely populated</td><td>人口稠密的</td></tr><tr><td>dense fog</td><td>浓雾</td></tr><tr><td>population density</td><td>人口密度</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a densely populated coastal strip.</p><blockquote><p>该地图显示了一条人口稠密的沿海地带。</p></blockquote><p><strong>Writing Task 2</strong> Dense urban form reduces transport emissions per person.</p><blockquote><p>高密度的城市形态能降低人均交通排放。</p></blockquote><p><strong>Speaking</strong> The fog was so dense we could barely see the road.</p><blockquote><p>雾太浓了，几乎看不清路。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>thick</td><td>浓密的</td><td>口语，形容雾、林</td></tr><tr><td>compact</td><td>紧密的</td><td>强调紧凑，非数量多</td></tr><tr><td>crowded</td><td>拥挤的</td><td>指人多，含不适感</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>densus</em>（浓密）</li><li><strong>Family:</strong> dense 密集的 / density 密度 / densely 密集地 / condense 凝结；压缩</li><li><strong>Memory Tip:</strong> 名词 density 是图表与地理的核心指标：population density（人口密度）、physical density（物理密度）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>副词是 densely：densely populated，不用 <s>dense populated</s>。</li><li>dense 形容雾、林、人口；&quot;拥挤&quot;用 crowded。</li><li>density 不可数（the density of…）。</li></ul></div><div class="vocab-card"><h2 id="intensity" tabindex="-1"><a class="header-anchor" href="#intensity"><span>Intensity</span></a></h2><p class="vc-meta"><strong>/ɪnˈtensəti/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>强度（可测量的量）</li><li>强烈，剧烈（感受、情绪）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>rainfall intensity</td><td>降雨强度</td></tr><tr><td>light intensity</td><td>光照强度</td></tr><tr><td>the intensity of</td><td>……的强度</td></tr><tr><td>energy intensity</td><td>能源强度</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows rainfall intensity increasing over the period.</p><blockquote><p>该图表显示了该时期降雨强度的上升。</p></blockquote><p><strong>Writing Task 2</strong> The intensity of tropical storms is expected to rise as seas warm.</p><blockquote><p>随着海水变暖，热带风暴的强度预计会上升。</p></blockquote><p><strong>Speaking</strong> The intensity of the heat was unbearable by noon.</p><blockquote><p>到中午时，酷热已经难以忍受。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>strength</td><td>强度</td><td>更泛用，非技术量</td></tr><tr><td>severity</td><td>严重程度</td><td>强调危害大小</td></tr><tr><td>force</td><td>力度</td><td>多指自然力、论点</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>intensus</em>（拉紧）← <em>tendere</em>（拉）</li><li><strong>Family:</strong> intensity 强度 / intense 强烈的 / intensify 加强 / intensive 密集的</li><li><strong>Memory Tip:</strong> 三个词分工明确：<strong>intense</strong> 形容感受强烈、<strong>intensity</strong> 是可测的强度、<strong>intensify</strong> 是动词&quot;加强&quot;。图表题里 rainfall intensity 是水文学固定说法。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>多用 the intensity of 结构，不可数。</li><li>rainfall intensity（降雨强度）与 rainfall amount（降雨量）不是一回事。</li><li>intense 与 intensive 不能互换，见下条。</li></ul></div><div class="vocab-card"><h2 id="intensive" tabindex="-1"><a class="header-anchor" href="#intensive"><span>Intensive</span></a></h2><p class="vc-meta"><strong>/ɪnˈtensɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>密集的，集约的（投入高）</li><li>强化的，集中的（课程、治疗）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>intensive farming</td><td>集约农业</td></tr><tr><td>intensive care</td><td>重症监护</td></tr><tr><td>an intensive course</td><td>强化课程</td></tr><tr><td>labour-intensive</td><td>劳动密集型的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows intensive agriculture concentrated along the river.</p><blockquote><p>该地图显示了集中在河流沿线的集约农业区。</p></blockquote><p><strong>Writing Task 2</strong> Intensive farming raises yields but depletes soil and groundwater.</p><blockquote><p>集约农业提高了产量，却消耗了土壤与地下水。</p></blockquote><p><strong>Speaking</strong> I did an intensive course — four hours a day for a month.</p><blockquote><p>我上了一个强化课程，每天四小时，连着一个月。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>concentrated</td><td>集中的</td><td>强调聚集，非投入高</td></tr><tr><td>thorough</td><td>彻底的</td><td>多形容检查、调查</td></tr><tr><td>high-input</td><td>高投入的</td><td>只对应农业义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 同 <em>intense</em>，均出自拉丁 <em>intensus</em></li><li><strong>Family:</strong> intensive 集约的 / intense 强烈的 / intensity 强度 / intensively 集约地</li><li><strong>Memory Tip:</strong> 一句话分清：<strong>intensive 讲&quot;投入密度&quot;，intense 讲&quot;感受强度&quot;</strong>。intensive farming（每亩投入大量化肥劳力）vs intense heat（酷热难耐）。这是中国学生最常混的一对。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>intensive ≠ intense，参见上条的区别。</li><li>intensive care 是&quot;重症监护&quot;，不是&quot;密集护理&quot;。</li><li>labour-intensive 等复合词带连字符。</li></ul></div><div class="vocab-card"><h2 id="flash" tabindex="-1"><a class="header-anchor" href="#flash"><span>Flash</span></a></h2><p class="vc-meta"><strong>/flæʃ/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：闪光，闪烁；飞速掠过</li><li>名词：闪光；一瞬间</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a flash of lightning</td><td>一道闪电</td></tr><tr><td>flash flood</td><td>山洪，骤发洪水</td></tr><tr><td>in a flash</td><td>一瞬间</td></tr><tr><td>flash by</td><td>一闪而过</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows areas at risk of flash flooding below steep catchments.</p><blockquote><p>该地图显示了陡峭集水区下方易发山洪的区域。</p></blockquote><p><strong>Writing Task 2</strong> News of the oil spill flashed around the world within hours.</p><blockquote><p>石油泄漏的消息几小时内就传遍全球。</p></blockquote><p><strong>Speaking</strong> A car flashed its lights at us to warn us about the police.</p><blockquote><p>一辆车朝我们闪大灯，提醒我们前面有警察。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sparkle</td><td>闪烁</td><td>持续闪耀，多指星光</td></tr><tr><td>gleam</td><td>微光</td><td>柔和反光</td></tr><tr><td>flare</td><td>骤然发光</td><td>突然且短暂</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拟态词，模拟瞬间亮光</li><li><strong>Family:</strong> flash 闪光 / flashy 浮华的 / flashlight 手电筒 / flash flood 山洪</li><li><strong>Memory Tip:</strong> <strong>flash flood 是&quot;山洪&quot;</strong>——陡坡集水区暴雨后几分钟内形成的洪水，灾害与地貌话题的高频词，与 river flood（河流洪水）机理不同。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>flash flood 分开写，两个词。</li><li>in a flash 是&quot;一瞬间&quot;，不是&quot;闪光中&quot;。</li><li>flash 与 flush（冲水、脸红）拼写接近，别混。</li></ul></div>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};